// ══════════════════════════════════════════════════════════════
// 排液控制程序（per-tank 并行 FSM，每扫描周期调用）
// ══════════════════════════════════════════════════════════════
// 程序名：PRG_TankDrain
// 文件名：plc_develop_drain.txt
// 职责：监控 Tank_Drain_Enable[1..8]，触发对应缸的 3 阶段排液流程
// 触发条件：Tank_Drain_Enable[i]=TRUE 且 Tank_State[i]=40
// 完成标志：Tank_Drain_Done[i]=TRUE, Tank_State[i]=99
// 复位方式：PC 写 Tank_Drain_Enable[i]=FALSE → 清 Done；
//           PC 写 Tank_State[i]=0 → 释放缸
// ══════════════════════════════════════════════════════════════
// 3 阶段排液时序（工程师已验证）：
//   Phase A — Draining(50)：开排液阀 + 真空泵，等待 DrainDuration
//   Phase B — BlowAir(55) ：追加开吹气阀，等待 BlowDuration
//   Phase C — CylinderRetract(60)：关所有阀 + 气缸退回，等待到位传感器
// ══════════════════════════════════════════════════════════════
// 硬件拓扑：
//   - 每缸有独立排液电磁阀、吹气电磁阀、气缸（伸出/退回）
//   - 真空泵（大真空泵）全局共享，anyDraining 引用计数式控制
//   - 排液气泡传感器按组共享（仅用于监控，不参与控制逻辑）
//   - 支持 8 缸完全并行排液（各缸 FSM 独立推进）
// ══════════════════════════════════════════════════════════════
// Tank_State 状态转换（排液相关）：
//   40 (Developing)      → 50 (Draining)        : Drain_Enable[i] 触发
//   50 (Draining)        → 55 (BlowAir)         : DrainTimer[i].Q
//   55 (BlowAir)         → 60 (CylinderRetract) : BlowTimer[i].Q
//   60 (CylinderRetract) → 99 (Done)            : 气缸到位传感器
//   99 (Done)            → 0  (Idle)            : PC 写 Tank_State=0
//   50/55/60             → 90 (Error)           : 急停
//   注：55/60 为 PLC 内部子状态，PC 只关心 Drain_Done（state 99）
// ══════════════════════════════════════════════════════════════
// 物理 IO 映射表（工程师变量名 → 缸索引）：
//   i=1: 展缸1排液电池阀1自动 / 展缸1吹气电池阀1自动 / 展缸1气缸1自动 / 展缸1气缸1动点
//   i=2: 展缸1排液电池阀2自动 / 展缸1吹气电池阀2自动 / 展缸1气缸2自动 / 展缸1气缸2动点
//   i=3: 展缸1排液电池阀3自动 / 展缸1吹气电池阀3自动 / 展缸1气缸3自动 / 展缸1气缸3动点
//   i=4: 展缸1排液电池阀4自动 / 展缸1吹气电池阀4自动 / 展缸1气缸4自动 / 展缸1气缸4动点
//   i=5: 展缸2排液电池阀1自动 / 展缸2吹气电池阀1自动 / 展缸2气缸1自动 / 展缸2气缸1动点
//   i=6: 展缸2排液电池阀2自动 / 展缸2吹气电池阀2自动 / 展缸2气缸2自动 / 展缸2气缸2动点
//   i=7: 展缸2排液电池阀3自动 / 展缸2吹气电池阀3自动 / 展缸2气缸3自动 / 展缸2气缸3动点
//   i=8: 展缸2排液电池阀4自动 / 展缸2吹气电池阀4自动 / 展缸2气缸4自动 / 展缸2气缸4动点
//   全局: 大真空泵自动
//   监控: 展缸1排液气泡传感器 / 展缸2排液气泡传感器
// ══════════════════════════════════════════════════════════════



// ══ 急停联锁：排液程序响应急停 ══
IF NOT 急停 THEN
    FOR i := 1 TO 8 DO
        // 急停时将所有排液中的缸（50/55/60）标记为 Error
        IF Tank_State[i] = 50 OR Tank_State[i] = 55 OR Tank_State[i] = 60 THEN
            Tank_State[i] := 90;
        END_IF
        // 停止所有定时器
        DrainTimer[i](IN := FALSE, PT := T#0S);
        BlowTimer[i](IN := FALSE, PT := T#0S);
        // 关闭所有排液阀和吹气阀
        CASE i OF
            1: 展缸1排液电池阀1自动 := FALSE; 展缸1吹气电池阀1自动 := FALSE;
            2: 展缸1排液电池阀2自动 := FALSE; 展缸1吹气电池阀2自动 := FALSE;
            3: 展缸1排液电池阀3自动 := FALSE; 展缸1吹气电池阀3自动 := FALSE;
            4: 展缸1排液电池阀4自动 := FALSE; 展缸1吹气电池阀4自动 := FALSE;
            5: 展缸2排液电池阀1自动 := FALSE; 展缸2吹气电池阀1自动 := FALSE;
            6: 展缸2排液电池阀2自动 := FALSE; 展缸2吹气电池阀2自动 := FALSE;
            7: 展缸2排液电池阀3自动 := FALSE; 展缸2吹气电池阀3自动 := FALSE;
            8: 展缸2排液电池阀4自动 := FALSE; 展缸2吹气电池阀4自动 := FALSE;
        END_CASE
    END_FOR
    // 关闭真空泵
    大真空泵站位[0] := FALSE;
    RETURN;
END_IF

// ══ 主循环：逐缸并行处理排液 FSM ══
FOR i := 1 TO 8 DO
 DrainTimer[i](IN := (Tank_State[i] = 50  AND  (i>4 AND 展缸2溶剂废液检测传感器)) OR (Tank_State[i] = 50 AND (i<5 AND 展缸1溶剂废液检测传感器)) , PT := DrainDuration);

 BlowTimer[i](IN := Tank_State[i] = 55, PT := BlowDuration);

    // ── 场景 1：PC 撤销 Drain_Enable → 复位 Done 标志（握手完成）──
    IF NOT Tank_Drain_Enable[i] THEN
        Tank_Drain_Done[i] := FALSE;
        DrainTimer[i](IN := FALSE, PT := T#0S);
        BlowTimer[i](IN := FALSE, PT := T#0S);
        // 注意：不主动修改 Tank_State，由 PC 写 0 释放
    // ── 场景 2：Drain_Enable=TRUE，缸处于 Developing(40)，启动排液 Phase A ──
    ELSIF Tank_Drain_Enable[i] AND Tank_State[i] = 40 THEN
        // 开启排液阀
		大真空泵站位[i] := TRUE;
        CASE i OF
            1: 展缸1排液电池阀1自动 := TRUE;
            2: 展缸1排液电池阀2自动 := TRUE;
            3: 展缸1排液电池阀3自动 := TRUE;
            4: 展缸1排液电池阀4自动 := TRUE;
            5: 展缸2排液电池阀1自动 := TRUE;
            6: 展缸2排液电池阀2自动 := TRUE;
            7: 展缸2排液电池阀3自动 := TRUE;
            8: 展缸2排液电池阀4自动 := TRUE;
        END_CASE
        // 推进状态至 Draining
        Tank_State[i] := 50;
    // ── 场景 3：Phase A — Draining(50)，排液阀开 + 真空泵运行，等待排液定时完成 ──
    ELSIF Tank_State[i] = 50 AND (i<5 AND 展缸1溶剂废液检测传感器) THEN

        IF DrainTimer[i].Q THEN
            // 排液定时完成，锁定并复位 DrainTimer
            DrainTimer[i](IN := FALSE, PT := T#0S);
            // 开启吹气阀（排液阀保持开启），进入 Phase B
            CASE i OF
                1: 展缸1吹气电池阀1自动 := TRUE;
                2: 展缸1吹气电池阀2自动 := TRUE;
                3: 展缸1吹气电池阀3自动 := TRUE;
                4: 展缸1吹气电池阀4自动 := TRUE;

            END_CASE
            Tank_State[i] := 55;
        END_IF
	ELSIF Tank_State[i] = 50  AND  (i>4AND 展缸2溶剂废液检测传感器) THEN

        IF DrainTimer[i].Q THEN
            // 排液定时完成，锁定并复位 DrainTimer
            DrainTimer[i](IN := FALSE, PT := T#0S);
            // 开启吹气阀（排液阀保持开启），进入 Phase B
            CASE i OF
                5: 展缸2吹气电池阀1自动 := TRUE;
                6: 展缸2吹气电池阀2自动 := TRUE;
                7: 展缸2吹气电池阀3自动 := TRUE;
                8: 展缸2吹气电池阀4自动 := TRUE;
            END_CASE
            Tank_State[i] := 55;
        END_IF
    // ── 场景 4：Phase B — BlowAir(55)，吹气阀开，等待吹气定时完成 ──
    ELSIF Tank_State[i] = 55 THEN
        大真空泵站位[i] := FALSE;
        IF BlowTimer[i].Q THEN
            // 吹气完成，锁定并复位 BlowTimer
            BlowTimer[i](IN := FALSE, PT := T#0S);
            // 关闭排液阀和吹气阀，启动气缸退回，进入 Phase C
            CASE i OF
                1: 展缸1排液电池阀1自动 := FALSE; 展缸1吹气电池阀1自动 := FALSE; 展缸1气缸1自动 := FALSE;
                2: 展缸1排液电池阀2自动 := FALSE; 展缸1吹气电池阀2自动 := FALSE; 展缸1气缸2自动 := FALSE;
                3: 展缸1排液电池阀3自动 := FALSE; 展缸1吹气电池阀3自动 := FALSE; 展缸1气缸3自动 := FALSE;
                4: 展缸1排液电池阀4自动 := FALSE; 展缸1吹气电池阀4自动 := FALSE; 展缸1气缸4自动 := FALSE;
                5: 展缸2排液电池阀1自动 := FALSE; 展缸2吹气电池阀1自动 := FALSE; 展缸2气缸1自动 := FALSE;
                6: 展缸2排液电池阀2自动 := FALSE; 展缸2吹气电池阀2自动 := FALSE; 展缸2气缸2自动 := FALSE;
                7: 展缸2排液电池阀3自动 := FALSE; 展缸2吹气电池阀3自动 := FALSE; 展缸2气缸3自动 := FALSE;
                8: 展缸2排液电池阀4自动 := FALSE; 展缸2吹气电池阀4自动 := FALSE; 展缸2气缸4自动 := FALSE;
            END_CASE
            Tank_State[i] := 60;
       END_IF
    // ── 场景 5：Phase C — CylinderRetract(60)，等待气缸退回到位 ──
    ELSIF Tank_State[i] = 60 THEN
        CASE i OF
            1: IF 展缸1气缸1原点 THEN   Tank_State[1] := 65; END_IF
            2: IF 展缸1气缸2原点 THEN   Tank_State[2] := 65; END_IF
            3: IF 展缸1气缸3原点 THEN   Tank_State[3] := 65; END_IF
            4: IF 展缸1气缸4原点 THEN   Tank_State[4] := 65; END_IF
            5: IF 展缸2气缸1原点 THEN   Tank_State[5] := 65; END_IF
            6: IF 展缸2气缸2原点 THEN   Tank_State[6] := 65; END_IF
            7: IF 展缸2气缸3原点 THEN   Tank_State[7] := 65; END_IF
            8: IF 展缸2气缸4原点 THEN   Tank_State[8] := 65; END_IF
        END_CASE

	 //场景 6：Phase D — RobotPickup(65)，等待机器人取板（电平握手，串行）──
    ELSIF Tank_State[i] = 65 THEN
		bParameterList1[i]:=TRUE;   //机器人参数取展缸位置

        IF RO_ParameterList1=i THEN
            // 机器人空闲 → 发出取板请求（电平保持）
			Tank_State[RO_ParameterList1] := 99;
			bParameterList1[i]:=FALSE;
			CASE i OF
            1:  Tank_Drain_Done[1] := TRUE; 
            2:   Tank_Drain_Done[2] := TRUE; 
            3:   Tank_Drain_Done[3] := TRUE;  
            4:   Tank_Drain_Done[4] := TRUE;  
            5:   Tank_Drain_Done[5] := TRUE;  
            6:   Tank_Drain_Done[6] := TRUE;  
            7:   Tank_Drain_Done[7] := TRUE;  
            8:   Tank_Drain_Done[8] := TRUE;  
        END_CASE
//             RobotRequested := TRUE;
//             Robot_Pickup_Req := TRUE;
//             Robot_Source_Tank := i;
        END_IF
//         IF RobotRequested AND Robot_Source_Tank = i AND Robot_Pickup_Done THEN
//             // 机器人取板完成 → 清除握手信号，标记排液完成
//             Robot_Pickup_Req := FALSE;
//             RobotRequested := FALSE;
//             Tank_Drain_Done[i] := TRUE;
//             
//         END_IF
	END_IF


END_FOR

// ══ 真空泵全局控制：当无任何缸在排液/吹气时关闭真空泵 ══

IF bParameterList1[1] OR bParameterList1[2]  OR  bParameterList1[3] OR bParameterList1[4] OR bParameterList1[5] OR bParameterList1[6] OR bParameterList1[7] OR bParameterList1[8]THEN
	展开工位允许取硅胶板:=TRUE;
END_IF
IF  展开工位允许取硅胶板 THEN
	IF bParameterList1[1] THEN
		ParameterList1:=1;
	ELSIF bParameterList1[2] THEN
		ParameterList1:=2;
	ELSIF bParameterList1[3] THEN
		ParameterList1:=3;
	ELSIF bParameterList1[4] THEN
		ParameterList1:=4;
	ELSIF bParameterList1[5] THEN
		ParameterList1:=5;
	ELSIF bParameterList1[6] THEN
		ParameterList1:=6;
	ELSIF bParameterList1[7] THEN
		ParameterList1:=7;
	ELSIF bParameterList1[8] THEN
		ParameterList1:=8;
	END_IF
END_IF
